// Converts all 51 celebrities into QuizPacks WITHOUT revealing question counts or scores in the description
export const CHASE_QUIZ_PACKS: QuizPack[] = CHASE_CELEBRITIES.map((celeb, cIdx) => ({
  id: `pack-chase-${cIdx}`,
  title: `Cash Builder: ${celeb.n}`,
  description: `Blind Duel vs ${celeb.n}! Beat their score for +3 bonus points (+1 for a tie).`,
  category: 'Cash Builder',
  icon: '⚡',
  questions: celeb.qs.map((item, qIdx): Question => {
    const isLast = qIdx === celeb.qs.length - 1;
    return {
      id: `chase_${cIdx}_${qIdx}`,
      type: 'TEXT',
      category: `Cash Builder: ${celeb.n}`,
      question: item.q,
      answer: item.a,
      points: 1,
      explanation: isLast
        ? `END OF MINUTE! ${celeb.n} was asked ${celeb.asked} questions and scored ${celeb.right} (£${celeb.right},000)! Beat ${celeb.right} for +3 bonus pts (+1 for a tie).`
        : undefined
    };
  })
}));
